import type { Amount, CastReceipt, DamageContext, EffectKeyTuple, Source, StatModifier, TargetSelector, TriggerDefinition } from '../../src/simulation/m8/contracts';
export const source = (definitionId = 'test', instanceId = 'i1', ownerId = 'u1'): Source => ({ ownerId, sourceKind: 'item', definitionId, instanceId, effectIndex: 0, parentItemInstanceId: null });
export const key = (s: Source, targetId = 'u1', applicationId = 'source'): string => JSON.stringify(['c1', s.ownerId, s.sourceKind, s.definitionId, s.instanceId, s.effectIndex, s.parentItemInstanceId, targetId, applicationId] satisfies EffectKeyTuple);
export const amount = (flat = 0, patch: Partial<Amount> = {}): Amount => ({ flat, attackDamageBps: 0, abilityPowerBps: 0, maxHpBps: 0, missingHpBps: 0, actualManaSpentBps: 0, actualDamageBps: 0, shieldAbsorbedBps: 0, hpBasis: 'holder', sample: 'application', cap: null, ...patch });
export const selector = (patch: Partial<TargetSelector> = {}): TargetSelector => ({ primary: 'normal', candidates: 'board', relation: 'self', anchor: 'holder', radius: null, maxTargets: 1, excludeSelf: false, excludePrimary: false, distinct: true, order: 'distance-id', sample: 'action-completion', ...patch });
export const modifier = (stat: StatModifier['stat'], value: number, patch: Partial<StatModifier> = {}): StatModifier => ({ stat, unit: 'flat', value: { kind: 'constant', amount: value }, condition: { kind: 'always' }, damageFilter: null, ...patch });
export const trigger = (patch: Partial<TriggerDefinition> = {}): TriggerDefinition => ({ id: 'trigger', source: source(), event: 'attack-completed', listener: { subject: 'actor', relationToHolder: 'self', withinHexes: null }, aggregation: 'event', counters: [], gate: { kind: 'always' }, condition: { kind: 'always' }, selector: selector(), internalCooldownTicks: 0, maxPerAction: 1, maxPerCombat: null, stackPolicy: { kind: 'independent-instances' }, effects: [], ...patch });
export const cast = (patch: Partial<CastReceipt> = {}): CastReceipt => ({ source: { ...source('ability'), sourceKind: 'ability' }, actionSeq: 1, completed: true, targetIds: ['A'], targetsSampledAtTick: 10, actualManaSpent: 80, refundedMana: 0, completionCell: { col: 3, row: 2 }, ...patch });
export const context = (patch: Partial<DamageContext> = {}): DamageContext => ({ source: source(), targetId: 'A', damageType: 'physical', delivery: 'ability-direct', actionSeq: 1, rootActionSeq: 1, parentPacketId: null, triggeringCastActionSeq: 1, packetId: 'p1', packetOrdinal: 0, equipmentDepth: 0, redirected: false, area: false, critEligibility: 'never', permissions: [], ...patch });
